class Solution {
  public long maxSubarraySum(int[] nums, int k) {
    long[] minPrefix = new long[k];
    Arrays.fill(minPrefix, Long.MAX_VALUE);
    long best = Long.MIN_VALUE, prefix = 0;
    minPrefix[0] = 0;
    for (int j = 1; j <= nums.length; j++) {
      prefix += nums[j - 1];
      int r = j % k;
      // a subarray whose length is a multiple of k starts at a prefix with the same residue
      if (minPrefix[r] != Long.MAX_VALUE) best = Math.max(best, prefix - minPrefix[r]);
      minPrefix[r] = Math.min(minPrefix[r], prefix);
    }
    return best;
  }
}
